import React, { useState, useEffect, useCallback } from 'react';
import { 
  AlertCircle, 
  CheckCircle, 
  Clock, 
  Server, 
  Wifi, 
  WifiOff,
  RefreshCw,
  X,
  Zap,
  Database
} from 'lucide-react';
import { useSocket } from '../contexts/SocketContext';

function SystemStatus({ onRefresh }) {
  const [status, setStatus] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lastChecked, setLastChecked] = useState(null);
  const [isMinimized, setIsMinimized] = useState(false);
  const [showNotification, setShowNotification] = useState(false);
  const [notification, setNotification] = useState(null);

  const { isConnected, connectionStatus, lastMessage } = useSocket();

  const fetchStatus = useCallback(async () => {
    try {
      const response = await fetch('/api/news/status');
      const data = await response.json();

      if (data.success) {
        setStatus(data.data);
        setLastChecked(new Date());
      }
    } catch (error) {
      console.error('获取状态失败:', error);
      setStatus({
        status: '错误',
        error: '无法连接到服务器',
        newsCount: 0,
        isUpdating: false
      });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchStatus();
    // 每60秒检查一次（减少请求频率）
    const interval = setInterval(fetchStatus, 60000);
    return () => clearInterval(interval);
  }, [fetchStatus]);

  // 监听WebSocket消息显示通知
  useEffect(() => {
    if (lastMessage) {
      if (lastMessage.type === 'news-update' && lastMessage.data?.totalSaved > 0) {
        setNotification({
          type: 'success',
          message: `新增 ${lastMessage.data.totalSaved} 条新闻`
        });
        setShowNotification(true);
        setTimeout(() => setShowNotification(false), 5000);

        // 刷新状态
        fetchStatus();
        if (onRefresh) onRefresh();
      } else if (lastMessage.type === 'daily-update') {
        setNotification({
          type: 'info',
          message: '每日新闻已更新'
        });
        setShowNotification(true);
        setTimeout(() => setShowNotification(false), 5000);
      }
    }
  }, [lastMessage, fetchStatus, onRefresh]);

  if (loading && !status) {
    return null; // 初始加载时不显示
  }

  const isDemo = status?.isDemo || status?.newsCount === 0;
  const isUpdating = status?.isUpdating;

  // 确定状态颜色和图标
  let statusColor = 'bg-green-500';
  let StatusIcon = CheckCircle;
  let statusText = '系统正常';

  if (!isConnected) {
    statusColor = 'bg-gray-500';
    StatusIcon = WifiOff;
    statusText = '离线模式';
  } else if (isUpdating) {
    statusColor = 'bg-blue-500';
    StatusIcon = RefreshCw;
    statusText = '更新中';
  } else if (isDemo) {
    statusColor = 'bg-yellow-500';
    StatusIcon = AlertCircle;
    statusText = '演示模式';
  } else if (status?.status === '错误') {
    statusColor = 'bg-red-500';
    StatusIcon = AlertCircle;
    statusText = '连接错误';
  }

  // 最小化视图
  if (isMinimized) {
    return (
      <div className="fixed bottom-4 right-4 z-50">
        <button
          onClick={() => setIsMinimized(false)}
          className={`${statusColor} text-white p-3 rounded-full shadow-lg hover:scale-110 transition-transform`}
          title={statusText}
        >
          <StatusIcon className={`w-5 h-5 ${isUpdating ? 'animate-spin' : ''}`} />
        </button>

        {/* 实时连接指示器 */}
        {isConnected && (
          <span className="absolute -top-1 -right-1 w-3 h-3 bg-green-400 rounded-full border-2 border-white animate-pulse" />
        )}
      </div>
    );
  }

  return (
    <>
      {/* 通知弹窗 */}
      {showNotification && notification && (
        <div className="fixed top-20 right-4 z-50 animate-slide-in">
          <div className={`${notification.type === 'success' ? 'bg-green-500' : 'bg-blue-500'} text-white px-4 py-3 rounded-lg shadow-lg flex items-center space-x-3`}>
            <Zap className="w-5 h-5" />
            <span className="font-medium">{notification.message}</span>
            <button 
              onClick={() => setShowNotification(false)}
              className="p-1 hover:bg-white/20 rounded"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}

      {/* 状态面板 */}
      <div className="fixed bottom-4 right-4 z-50">
        <div className={`${statusColor} text-white px-4 py-3 rounded-xl shadow-lg max-w-xs backdrop-blur-sm`}>
          <div className="flex items-start space-x-3">
            <StatusIcon className={`w-5 h-5 mt-0.5 flex-shrink-0 ${isUpdating ? 'animate-spin' : ''}`} />
            <div className="flex-1 min-w-0">
              <div className="flex items-center justify-between">
                <h4 className="font-medium text-sm flex items-center">
                  {statusText}
                  {isConnected && (
                    <Wifi className="w-3 h-3 ml-2 text-white/80" />
                  )}
                </h4>
                <div className="flex items-center space-x-2">
                  <span className="text-xs opacity-75 flex items-center">
                    <Clock className="w-3 h-3 mr-1" />
                    {lastChecked ? lastChecked.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) : ''}
                  </span>
                  <button
                    onClick={() => setIsMinimized(true)}
                    className="p-1 hover:bg-white/20 rounded transition-colors"
                    title="最小化"
                  >
                    <X className="w-3 h-3" />
                  </button>
                </div>
              </div>

              <div className="mt-2 space-y-1 text-xs opacity-90">
                {/* 新闻数量 */}
                <div className="flex items-center justify-between">
                  <span className="flex items-center">
                    <Database className="w-3 h-3 mr-1.5" />
                    新闻数量
                  </span>
                  <span className="font-medium">{status?.newsCount || 0} 条</span>
                </div>

                {/* 连接状态 */}
                <div className="flex items-center justify-between">
                  <span className="flex items-center">
                    <Server className="w-3 h-3 mr-1.5" />
                    WebSocket
                  </span>
                  <span className={`font-medium ${isConnected ? 'text-green-200' : 'text-red-200'}`}>
                    {connectionStatus === 'connected' ? '已连接' : 
                     connectionStatus === 'reconnecting' ? '重连中' :
                     connectionStatus === 'error' ? '错误' : '断开'}
                  </span>
                </div>

                {/* 分类信息 */}
                {status?.categories && status.categories.length > 0 && (
                  <div className="flex items-center justify-between">
                    <span>分类</span>
                    <span className="truncate max-w-[120px]">
                      {status.categories.slice(0, 3).map(c => c.name).join(', ')}
                    </span>
                  </div>
                )}
              </div>

              {/* 错误信息 */}
              {status?.error && (
                <div className="mt-2 p-2 bg-black/20 rounded text-xs">
                  {status.error}
                </div>
              )}

              {/* 演示模式提示 */}
              {isDemo && !status?.error && (
                <div className="mt-2 text-xs opacity-80">
                  系统正在连接真实RSS源...
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* CSS动画 */}
      <style jsx>{`
        @keyframes slide-in {
          from {
            transform: translateX(100%);
            opacity: 0;
          }
          to {
            transform: translateX(0);
            opacity: 1;
          }
        }
        .animate-slide-in {
          animation: slide-in 0.3s ease-out;
        }
      `}</style>
    </>
  );
}

export default SystemStatus;
